@import "tailwindcss";
@import "@fontsource-variable/bricolage-grotesque";
@import "@fontsource/atkinson-hyperlegible-next/400.css";
@import "@fontsource/atkinson-hyperlegible-next/700.css";

/*
  Ward's looks. Every look is a night with one light in it: a dark room and a single warm
  accent ("glow"). The child picks one in onboarding and can switch any time in Settings.
  data-age sets how playful the shapes and type feel: 8 (8 to 10), 11 (11 to 13), 14 (14 to 17).
  Semantic colours (alarm, safe) stay the same in every look so danger always reads as danger.
*/

@theme {
  --font-display: "Bricolage Grotesque Variable", ui-sans-serif, system-ui, sans-serif;
  --font-sans: "Atkinson Hyperlegible Next", ui-sans-serif, system-ui, sans-serif;

  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-raised: var(--raised);
  --color-line: var(--line);
  --color-ink: var(--ink);
  --color-dim: var(--dim);
  --color-glow: var(--glow);
  --color-glow-ink: var(--glow-ink);
  --color-glow-soft: var(--glow-soft);
  --color-alarm: var(--alarm);
  --color-alarm-soft: var(--alarm-soft);
  --color-safe: var(--safe);

  --radius-card: var(--r-card);
  --radius-btn: var(--r-btn);
}

:root,
[data-look="lantern"] {
  --bg: #0f1024;
  --surface: #171933;
  --raised: #20234a;
  --line: rgb(226 224 255 / 0.09);
  --ink: #f4f0e8;
  --dim: #aeadc8;
  --glow: #ffb547;
  --glow-ink: #241500;
  --glow-soft: rgb(255 181 71 / 0.14);
  --halo: rgb(255 170 60 / 0.38);
}

[data-look="moonlit"] {
