function greeting(h = new Date().getHours()) {
  if (h < 5) return "Still up";
  if (h < 12) return "Morning";
  if (h < 17) return "Afternoon";
  return "Evening";
}

export function Home() {
  const p = useStore((s) => s.profile);
  const streak = liveStreak(p);
  const up = nextLesson(p.age, p.done);
  const late = new Date().getHours() >= 23 || new Date().getHours() < 5;
  const lastBad = p.checks.find((c) => c.level === "bullying" || c.level === "urgent");

  let mood: Mood = "happy";
  let line = "Got a chat that feels off? Show me. I'll read it here and tell you what I see.";
  if (late) {
    mood = "sleep";
    line = "It's late. Mean messages feel worse at night. They'll still be there in the morning, and so will I.";
  } else if (lastBad && Date.now() - lastBad.at < 3 * 86_400_000) {
    mood = "calm";
    line = "How are you doing after that chat? You don't have to deal with it on your own.";
  } else if (streak >= 3) {
    mood = "cheer";
    line = `${streak} days in a row. You're getting harder to knock down.`;
  }

  return (
    <Screen wide>
      <header className="flex items-center justify-between gap-3">
        <p className="font-display text-xl font-semibold tracking-tight text-dim">
          {greeting()}
          {p.name ? <span className="text-ink">, {p.name}</span> : null}
        </p>
        <div className="flex items-center gap-2">
          <Pill tone={streak ? "glow" : "quiet"}>
            <Fire size={16} weight="fill" /> {streak}
          </Pill>
          <Pill>
            <Lightning size={16} weight="fill" /> {p.xp} XP
          </Pill>
        </div>
      </header>

      <div className="mt-6 grid gap-5 lg:grid-cols-[1.35fr_1fr] lg:gap-6">
        <section className="relative overflow-hidden rounded-card border border-line bg-surface p-6 sm:p-8">
          <div className="flex flex-col items-start gap-6 sm:flex-row sm:items-center">
            <Ghost mood={mood} size={p.age === "14" ? 92 : 116} />
            <div className="min-w-0">
              <p className="max-w-[36ch] text-[1.15rem] leading-relaxed">{line}</p>
              <Button className="mt-5" onClick={() => go({ name: "check" })}>
                <MagnifyingGlass size={20} weight="bold" /> Check a chat
              </Button>
            </div>
          </div>
        </section>

        {up ? (
          <button
            onClick={() => go({ name: "lesson", id: up.lesson.id })}
            className="group flex flex-col justify-between rounded-card border border-line bg-raised p-6 text-left transition-transform active:scale-[0.99]"
          >
            <div className="flex items-center gap-3 text-glow">
              <UnitIcon icon={up.unit.icon} />
              <span className="font-display font-semibold">{up.unit.title}</span>
            </div>
            <div className="mt-6">
              <p className="font-display text-2xl font-bold tracking-tight">{up.lesson.title}</p>
              <p className="mt-1 text-dim">{up.lesson.line}</p>
            </div>
            <span className="mt-6 inline-flex items-center gap-2 font-display font-semibold text-glow">
              {streak && p.lastLessonDay === new Date().toISOString().slice(0, 10) ? "One more?" : "Today's lesson"}
              <ArrowRight size={18} weight="bold" className="transition-transform group-hover:translate-x-1" />
            </span>
          </button>
        ) : (
          <Card className="p-6">
            <p className="font-display text-xl font-bold">Path complete</p>
            <p className="mt-1 text-dim">You've done every lesson for your age. Replay any of them from Path.</p>
          </Card>
        )}
      </div>

      <section className="mt-10">
        <div className="flex items-end justify-between">
          <h2 className="font-display text-xl font-bold tracking-tight">Recent checks</h2>
          {p.checks.length > 0 && (
            <button className="text-sm font-bold text-glow" onClick={() => tab({ name: "vault" })}>
              Vault
            </button>
          )}
        </div>
        {p.checks.length === 0 ? (
          <p className="mt-3 max-w-[50ch] text-dim">
            Nothing yet. When you check a chat, a short note appears here: what I found, never the messages themselves.
          </p>
        ) : (
          <ul className="mt-3 grid gap-2">
            {p.checks.slice(0, 5).map((c) => (
              <li key={c.id} className="flex items-center gap-4 rounded-card border border-line bg-surface px-4 py-3.5">
                <LevelPill level={c.level} />
                <span className="min-w-0 flex-1 truncate font-semibold">{c.title}</span>
                {c.saved && <LockKey size={18} className="shrink-0 text-dim" aria-label="Saved in vault" />}
                <span className="shrink-0 text-sm text-dim">{new Date(c.at).toLocaleDateString(undefined, { day: "numeric", month: "short" })}</span>
              </li>
            ))}
          </ul>
        )}
      </section>
    </Screen>
  );
}

import type { Level } from "@ward/engine";
import { Pill } from "./ui.tsx";

export const LEVEL_LABEL: Record<Level, string> = {
  calm: "Looks okay",
  watch: "Keep an eye",
  bullying: "Bullying",
  urgent: "Get help now",
};

export function LevelPill({ level }: { level: Level }) {
  const tone = level === "urgent" || level === "bullying" ? "alarm" : level === "watch" ? "glow" : "safe";
  return <Pill tone={tone}>{LEVEL_LABEL[level]}</Pill>;
}

import { Camera, ChatsCircle, Eye, HandPalm, Heart, LockKey, UsersThree } from "@phosphor-icons/react";
import type { Unit } from "@ward/lessons";

const ICONS = { eye: Eye, hand: HandPalm, camera: Camera, chat: ChatsCircle, users: UsersThree, lock: LockKey, heart: Heart };

export function UnitIcon({ icon, size = 22, weight = "bold" }: { icon: Unit["icon"]; size?: number; weight?: "bold" | "fill" | "regular" }) {
  const I = ICONS[icon];
  return <I size={size} weight={weight} />;
}

// Running a check. The slang packs and pattern engine answer instantly, so the child sees
// something within a moment; then, if a model is available on this device, Gemma reads the
// chat with context and the result sharpens in place.

import { unzipSync, strFromU8 } from "fflate";
import { analyze, GemmaJudge, ollamaModels, parseChat, type Chat } from "@ward/engine";
import { getState, go, patchSession, putSession, uid, updateProfile } from "./store.ts";

export async function readChatFile(file: File): Promise<{ text: string; title: string }> {
  const base = file.name.replace(/\.(txt|zip)$/i, "");
  const title = base.replace(/^WhatsApp Chat (with|-) /i, "").trim() || "Chat";
  if (/\.zip$/i.test(file.name)) {
    const files = unzipSync(new Uint8Array(await file.arrayBuffer()));
    const name = Object.keys(files).find((n) => /(^|\/)_chat\.txt$/i.test(n)) ?? Object.keys(files).find((n) => n.toLowerCase().endsWith(".txt"));
    if (!name) throw new Error("That zip has no chat text in it. Export again and choose \"Without media\".");
    return { text: strFromU8(files[name]!), title };
  }
  return { text: await file.text(), title };
}

export function parse(text: string): Chat {
  return parseChat(text);
}

export type ModelStatus = { ok: true; model: string } | { ok: false; reason: string };

export async function modelStatus(): Promise<ModelStatus> {
  const { ollamaUrl, model } = getState().profile;
  const models = await ollamaModels(ollamaUrl);
  if (!models.length) return { ok: false, reason: "No model running on this device" };
  if (!models.includes(model)) return { ok: false, reason: `${model} isn't downloaded` };
  return { ok: true, model };
}

export async function startCheck(chat: Chat, self: string | null, title: string) {
  const id = uid();
  const quick = await analyze(chat, { self });
  putSession(id, { chat, analysis: quick, title, self, refining: true });
  updateProfile((p) => ({
    checks: [
      { id, at: Date.now(), title, level: quick.level, hostile: quick.findings.filter((f) => f.severity > 0).length, saved: false },
      ...p.checks,
    ].slice(0, 50),
  }));
  go({ name: "result", id });

  const status = await modelStatus();
  if (!status.ok) {
    patchSession(id, { refining: false, modelError: status.reason });
    return id;
  }
  try {
    const { ollamaUrl } = getState().profile;
    const full = await analyze(chat, {
      self,
      judges: [new GemmaJudge({ baseUrl: ollamaUrl, model: status.model, batch: 16 })],
      onProgress: (d, t) => patchSession(id, { progress: [d, t] }),
    });
    patchSession(id, { analysis: full, refining: false, progress: undefined });
    updateProfile((p) => ({
      checks: p.checks.map((c) => (c.id === id ? { ...c, level: full.level, hostile: full.findings.filter((f) => f.severity > 0).length } : c)),
    }));
  } catch (e) {
    patchSession(id, { refining: false, modelError: e instanceof Error ? e.message : String(e) });
  }
  return id;
}

/** Screenshots: Gemma's vision reads them into "Name: message" lines. Desktop with Ollama only for now. */
export async function readScreenshots(files: File[]): Promise<string> {
  const { ollamaUrl, model } = getState().profile;
  const images = await Promise.all(
    files.map(
      (f) =>
        new Promise<string>((res, rej) => {
          const r = new FileReader();
          r.onload = () => res(String(r.result).split(",")[1]!);
          r.onerror = () => rej(r.error);
          r.readAsDataURL(f);
        }),
    ),
  );
  const out: string[] = [];
  for (const img of images) {
    const r = await fetch(`${ollamaUrl}/api/chat`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        model,
        stream: false,
        think: false,
        options: { temperature: 0 },
        messages: [
          {
            role: "user",
            content:
              "This is a screenshot of a chat app. Write out every message, top to bottom, one per line, as `Name: message`. Use the sender name shown in the screenshot; for messages sent by the phone's owner (usually on the right), use `Me`. Copy the text exactly, in whatever language it is in. Output only the lines.",
            images: [img],
          },
        ],
      }),
    });
    if (!r.ok) throw new Error(`Couldn't read the screenshot (${r.status})`);
    const j = (await r.json()) as { message: { content: string } };
    out.push(j.message.content.trim());
  }
  return out.join("\n");
}

// A drop zone with a glowing rim and a light that travels around its edge, adapted from the
// idea in cult-ui's Halo Dropzone (21st.dev): a CSS offset-path trail plus slow blobs of the
// look's glow pooled at the bottom. Pure CSS motion, stopped under reduced motion.

import { useRef, useState, type ReactNode } from "react";
import { UploadSimple } from "@phosphor-icons/react";

export function HaloDrop({ accept, multiple, onFiles, children }: { accept: string; multiple?: boolean; onFiles: (files: File[]) => void; children?: ReactNode }) {
  const input = useRef<HTMLInputElement>(null);
  const [over, setOver] = useState(false);

  return (
    <div
      onDragOver={(e) => {
        e.preventDefault();
        setOver(true);
      }}
      onDragLeave={() => setOver(false)}
      onDrop={(e) => {
        e.preventDefault();
        setOver(false);
        const files = [...e.dataTransfer.files];
        if (files.length) onFiles(files);
      }}
      className={`relative isolate overflow-hidden rounded-card border transition-colors ${over ? "border-glow bg-glow-soft" : "border-line bg-surface"}`}
    >
      {/* travelling light on the rim */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] border border-transparent [mask-clip:padding-box,border-box] [mask-composite:intersect] [mask-image:linear-gradient(transparent,transparent),linear-gradient(#000,#000)]"
      >
        <div
          className="absolute h-6 w-40 rounded-full"
          style={{
            offsetPath: "rect(0 auto auto 0 round var(--r-card))",
            offsetDistance: "0%",
            animation: `rim-trail ${over ? 2.2 : 7}s linear infinite`,
            background: "radial-gradient(closest-side, var(--glow), transparent)",
            filter: "blur(3px)",
          }}
        />
      </div>
      {/* light pooled at the bottom */}
      <div aria-hidden className="pointer-events-none absolute inset-x-0 bottom-0 -z-10 h-1/2">
        <div className="absolute -bottom-12 left-1/4 h-28 w-2/3 rounded-full blur-3xl" style={{ background: "var(--glow)", opacity: over ? 0.35 : 0.14, animation: "rim-drift 9s ease-in-out infinite" }} />
      </div>

      <button type="button" onClick={() => input.current?.click()} className="flex w-full flex-col items-center gap-3 px-6 py-10 text-center">
        <span className="grid size-14 place-items-center rounded-full bg-raised text-glow" style={{ animation: "ward-float 3.5s ease-in-out infinite" }}>
          <UploadSimple size={26} weight="bold" />
        </span>
        {children}
      </button>
      <input
        ref={input}
        type="file"
        accept={accept}
        multiple={multiple}
        className="sr-only"
        onChange={(e) => {
          const files = [...(e.target.files ?? [])];
          e.target.value = "";
          if (files.length) onFiles(files);
        }}
      />
    </div>
  );
}

// Check a chat: bring it in (WhatsApp export, paste, or screenshots), say which person is you,
// and Ward reads it on the device.

import { useState } from "react";
import { CaretDown, ClipboardText, ImageSquare, Sparkle, UserCircle, UsersThree } from "@phosphor-icons/react";
import type { Chat } from "@ward/engine";
import sample from "../../../../packages/engine/fixtures/pileon-roman-urdu.txt?raw";
import { Ghost } from "../components/Ghost.tsx";
import { HaloDrop } from "../components/HaloDrop.tsx";
import { BackBar, Button, Screen } from "../components/ui.tsx";
import { parse, readChatFile, readScreenshots, startCheck } from "../lib/run.ts";
import { useStore } from "../lib/store.ts";

type Stage = { at: "input" } | { at: "who"; chat: Chat; title: string };

export function Check() {
  const name = useStore((s) => s.profile.name);
  const [stage, setStage] = useState<Stage>({ at: "input" });
  const [paste, setPaste] = useState("");
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [howOpen, setHowOpen] = useState(false);

  async function take(text: string, title: string) {
    setError(null);
    const chat = parse(text);
    if (chat.messages.length < 2) {
      setError("I couldn't find a conversation in that. Try exporting the chat again, or paste a few messages.");
      return;
    }
    setStage({ at: "who", chat, title });
  }

  async function onFiles(files: File[]) {
    setError(null);
    try {
      if (files.every((f) => f.type.startsWith("image/"))) {
        setBusy("Reading your screenshots");
        const text = await readScreenshots(files);
        setBusy(null);
        return take(text, "Screenshots");
      }
      const { text, title } = await readChatFile(files[0]!);
      return take(text, title);
    } catch (e) {
      setBusy(null);
      setError(e instanceof Error ? e.message : "Something went wrong reading that file.");
    }
  }

  if (stage.at === "who") return <WhoAreYou chat={stage.chat} title={stage.title} myName={name} onBack={() => setStage({ at: "input" })} />;

  return (
    <Screen>
      <h1 className="font-display text-3xl font-bold tracking-tight sm:text-4xl">Check a chat</h1>
      <p className="mt-2 max-w-[48ch] text-dim">Show me a conversation and I'll tell you what I see. I read it right here. It never leaves this device.</p>

      <div className="mt-6">
        {busy ? (
          <div className="flex flex-col items-center gap-4 rounded-card border border-line bg-surface px-6 py-12 text-center">
            <Ghost mood="think" size={84} />
            <p className="font-display text-lg font-semibold">{busy}…</p>
          </div>
        ) : (
          <HaloDrop accept=".txt,.zip,image/*" multiple onFiles={onFiles}>
            <span className="font-display text-xl font-semibold">Drop a WhatsApp export or screenshots</span>
            <span className="text-sm text-dim">Or tap to choose a file (.txt, .zip, or images)</span>
          </HaloDrop>
        )}
      </div>

      <div className="mt-3">
        <button onClick={() => setHowOpen((o) => !o)} aria-expanded={howOpen} className="flex min-h-11 items-center gap-2 text-sm font-bold text-glow">
          How do I export a WhatsApp chat?
          <CaretDown size={16} weight="bold" className={`transition-transform ${howOpen ? "rotate-180" : ""}`} />
        </button>
        {howOpen && (
          <ol className="mt-2 grid list-decimal gap-1.5 pl-5 text-dim marker:font-bold marker:text-glow">
            <li>Open the chat in WhatsApp.</li>
            <li>
              Android: tap <b className="text-ink">⋮</b>, then <b className="text-ink">More</b>, then <b className="text-ink">Export chat</b>. iPhone: tap the name at the top, then <b className="text-ink">Export chat</b>.
            </li>
            <li>
              Choose <b className="text-ink">Without media</b>, and share it to Ward (or save it and drop it here).
            </li>
          </ol>
        )}
      </div>

      <div className="mt-8">
        <label htmlFor="paste" className="flex items-center gap-2 font-display text-lg font-semibold">
          <ClipboardText size={22} weight="bold" className="text-glow" /> Or paste messages
        </label>
        <textarea
          id="paste"
          value={paste}
          onChange={(e) => setPaste(e.target.value)}
          rows={6}
          placeholder={"Hamza: lol did you see her photo\nBilal: so fat haha\nMe: please stop"}
          className="mt-2 w-full resize-y rounded-card border border-line bg-surface p-4 text-[1rem] leading-relaxed text-ink placeholder:text-dim/70 focus:border-glow focus:outline-none"
        />
        <p className="mt-1.5 text-sm text-dim">One message per line. "Name: message" helps me tell people apart.</p>
        <Button className="mt-3" disabled={!paste.trim()} onClick={() => take(paste, "Pasted chat")}>
          Check this
        </Button>
      </div>

      {error && (
        <p role="alert" className="mt-6 rounded-card bg-alarm-soft p-4 font-semibold text-alarm">
          {error}
        </p>
      )}

      <div className="mt-10 flex flex-wrap items-center gap-3 border-t border-line pt-6">
        <span className="flex items-center gap-2 text-dim">
          <ImageSquare size={20} /> Just looking around?
        </span>
        <Button tone="quiet" onClick={() => take(sample, "8B Science (example)")}>
          <Sparkle size={18} weight="bold" /> Try an example chat
        </Button>
      </div>
    </Screen>
  );
}

function WhoAreYou({ chat, title, myName, onBack }: { chat: Chat; title: string; myName: string; onBack: () => void }) {
  const guess = chat.participants.find((p) => myName && p.toLowerCase().startsWith(myName.toLowerCase().split(" ")[0]!)) ?? null;
  const [self, setSelf] = useState<string | null>(guess);
  const [starting, setStarting] = useState(false);
  const counts = new Map<string, number>();
  for (const m of chat.messages) counts.set(m.sender, (counts.get(m.sender) ?? 0) + 1);

  return (
    <Screen>
      <div className="mb-2">
        <button onClick={onBack} className="text-sm font-bold text-dim hover:text-ink">
          ← Choose a different chat
        </button>
      </div>
      <BackBar />
      <h1 className="font-display text-3xl font-bold tracking-tight">Which one is you?</h1>
      <p className="mt-2 text-dim">
        {chat.messages.length} messages in <b className="text-ink">{title}</b>. So I know who's being talked to.
      </p>
      <div className="mt-6 grid gap-2 sm:grid-cols-2">
        {chat.participants.slice(0, 24).map((p) => (
          <button
            key={p}
            onClick={() => setSelf(p)}
            aria-pressed={self === p}
            className={`flex min-h-14 items-center gap-3 rounded-btn border px-4 text-left transition-colors ${self === p ? "border-glow bg-glow-soft" : "border-line bg-surface hover:border-dim/40"}`}
          >
            <UserCircle size={26} weight={self === p ? "fill" : "regular"} className={self === p ? "text-glow" : "text-dim"} />
            <span className="min-w-0 flex-1 truncate font-semibold">{p}</span>
            <span className="text-sm text-dim">{counts.get(p) ?? 0}</span>
          </button>
        ))}
        <button
          onClick={() => setSelf(null)}
          aria-pressed={self === null}
          className={`flex min-h-14 items-center gap-3 rounded-btn border px-4 text-left transition-colors sm:col-span-2 ${self === null ? "border-glow bg-glow-soft" : "border-line bg-surface hover:border-dim/40"}`}
        >
          <UsersThree size={26} className={self === null ? "text-glow" : "text-dim"} />
          <span className="font-semibold">I'm checking it for a friend</span>
        </button>
      </div>
      <Button
        className="mt-8 w-full sm:w-auto"
        disabled={starting}
        onClick={async () => {
          setStarting(true);
          await startCheck(chat, self, title);
        }}
      >
        Read it, Ward
      </Button>
    </Screen>
  );
}

