            <div>
              <h1 className={`font-display text-2xl font-bold leading-tight tracking-tight sm:text-3xl ${a.level === "urgent" ? "text-alarm" : ""}`}>{v.title}</h1>
              <p className="mt-2 leading-relaxed">{v.line}</p>
            </div>
