function RefineStatus({ refining, progress, error }: { refining: boolean; progress?: [number, number]; error?: string }) {
  if (refining)
    return (
      <Pill tone="glow">
        <span className="size-2 animate-pulse rounded-full bg-glow" aria-hidden />
        Reading closely{progress ? ` ${progress[0]}/${progress[1]}` : ""}
      </Pill>
    );
  if (error) return <Pill>Quick check</Pill>;
  return null;
}

function Who({ analysis, self }: { analysis: Analysis; self: string | null }) {
  const ghosts = new Set(analysis.patterns.find((p) => p.kind === "ghosts")?.senders ?? []);
  const people = analysis.senders.filter((x) => x.hostile > 0 && x.name !== self);
  const upstanders = analysis.senders.filter((x) => x.hostile === 0 && x.name !== self && x.total > 0);
  return (
    <section aria-labelledby="who">
      <h2 id="who" className="font-display text-lg font-bold tracking-tight">
        Who
      </h2>
      <ul className="mt-3 flex flex-wrap gap-2">
        {people.map((x) => (
          <li key={x.name} className={`flex items-center gap-2 rounded-full border px-3 py-1.5 ${x.worst >= 3 ? "border-alarm/50" : "border-line"}`}>
            {ghosts.has(x.name) && <GhostIcon size={16} weight="fill" className="text-glow" aria-label="ghost account" />}
            <span className="font-semibold">{x.name}</span>
            <span className="text-sm text-dim">{x.hostile}</span>
          </li>
        ))}
      </ul>
      {upstanders.length > 0 && (
        <p className="mt-3 text-sm text-dim">
          Not part of it: {upstanders.slice(0, 4).map((u) => u.name).join(", ")}
          {upstanders.length > 4 ? ` and ${upstanders.length - 4} more` : ""}.
        </p>
      )}
    </section>
  );
}

function HowWardKnows({ analysis }: { analysis: Analysis }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="text-sm">
      <button onClick={() => setOpen((o) => !o)} aria-expanded={open} className="flex min-h-11 items-center gap-2 font-bold text-dim hover:text-ink">
        How I worked this out
        <CaretDown size={14} weight="bold" className={open ? "rotate-180" : ""} />
      </button>
      {open && (
        <div className="grid gap-2 text-dim">
          <p>
            Word lists for {analysis.layers.packs.length} languages ran instantly.
            {analysis.layers.models.length
              ? ` Then ${analysis.layers.models.join(" and ")} read the whole chat on this device, with context, so friends joking around don't count as bullying.`
              : " No AI model was running, so this is a quick check from word lists and patterns. Open Ward on a computer with Gemma for a closer read."}
          </p>
          <p>Nothing was sent anywhere. Patterns like pile-ons and ghost accounts come from who said what, when.</p>
        </div>
      )}
    </div>
  );
}

type Row = { kind: "msg"; f: Finding } | { kind: "fold"; count: number; from: number } | { kind: "day"; label: string } | { kind: "event"; text: string };

function Timeline({ analysis, self }: { analysis: Analysis; self: string | null }) {
  const [unfolded, setUnfolded] = useState<Set<number>>(new Set());
  const rows = useMemo(() => {
    const out: Row[] = [];
    let lastDay = "";
    let quiet: Finding[] = [];
    const flushQuiet = () => {
      if (!quiet.length) return;
      // Keep one line of context either side of an attack; fold longer quiet stretches.
      if (quiet.length <= 3 || unfolded.has(quiet[0]!.message.id)) quiet.forEach((f) => out.push({ kind: "msg", f }));
      else {
        out.push({ kind: "msg", f: quiet[0]! });
        out.push({ kind: "fold", count: quiet.length - 2, from: quiet[0]!.message.id });
        out.push({ kind: "msg", f: quiet.at(-1)! });
      }
      quiet = [];
    };
    const events = [...analysis.findings.length ? [] : []];
    void events;
    for (const f of analysis.findings) {
      const day = f.message.at ? f.message.at.toLocaleDateString(undefined, { weekday: "short", day: "numeric", month: "short" }) : "";
      if (day && day !== lastDay) {
        flushQuiet();
        out.push({ kind: "day", label: day });
        lastDay = day;
      }
      const loud = f.severity > 0 && f.message.sender !== self;
      if (loud) {
        flushQuiet();
        out.push({ kind: "msg", f });
      } else quiet.push(f);
    }
    flushQuiet();
    return out;
  }, [analysis, self, unfolded]);

  return (
    <section aria-labelledby="timeline" className="rounded-card border border-line bg-surface p-4 sm:p-6">
      <div className="flex items-center gap-2">
        <ChatsCircle size={22} weight="bold" className="text-glow" />
        <h2 id="timeline" className="font-display text-lg font-bold tracking-tight">
          The chat
        </h2>
        <span className="ml-auto text-sm text-dim">{analysis.findings.length} messages</span>
      </div>
      <ol className="mt-4 grid gap-2">
        {rows.map((r, i) => {
          if (r.kind === "day")
            return (
              <li key={`d${i}`} className="py-2 text-center text-xs font-bold uppercase tracking-wider text-dim">
                {r.label}
              </li>
            );
          if (r.kind === "fold")
            return (
              <li key={`f${r.from}`} className="text-center">
                <button onClick={() => setUnfolded((u) => new Set(u).add(r.from))} className="min-h-10 rounded-full px-3 text-sm font-bold text-dim hover:bg-raised hover:text-ink">
                  {r.count} ordinary messages
                </button>
              </li>
            );
          if (r.kind === "event") return null;
          return <Bubble key={r.f.message.id} f={r.f} mine={r.f.message.sender === self} />;
        })}
      </ol>
    </section>
  );
}

function Bubble({ f, mine }: { f: Finding; mine: boolean }) {
  const m = f.message;
  const loud = f.severity > 0 && !mine;
  const late = m.at && (m.at.getHours() >= 23 || m.at.getHours() < 5);
  const edge = f.severity >= 3 ? "border-alarm bg-alarm-soft" : f.severity === 2 ? "border-glow/70 bg-glow-soft" : f.severity === 1 ? "border-line bg-raised" : "border-transparent bg-raised/60";
  return (
    <li className={`flex flex-col ${mine ? "items-end" : "items-start"}`}>
      <div className={`max-w-[88%] rounded-[calc(var(--r-card)-6px)] border px-4 py-2.5 ${mine ? "border-transparent bg-glow-soft" : loud ? edge : "border-transparent bg-raised/60"}`}>
        <div className="flex items-center gap-2 text-xs">
          <span className={`font-bold ${loud ? "text-ink" : "text-dim"}`}>{mine ? "You" : m.sender}</span>
          {m.at && (
            <span className="text-dim">
              {m.at.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" })}
              {late && <MoonStars size={12} weight="fill" className="ml-1 inline text-glow" aria-label="late at night" />}
            </span>
          )}
        </div>
        <p className={`mt-0.5 whitespace-pre-wrap break-words ${loud ? "" : "text-dim"}`}>{m.media ? <i>photo or video</i> : m.text}</p>
      </div>
      {loud && f.why && (
        <p className={`mt-1 max-w-[88%] px-1 text-sm ${f.severity >= 3 ? "font-bold text-alarm" : "text-dim"}`}>
          {f.severity >= 3 && <Warning size={14} weight="fill" className="mr-1 inline" />}
          {f.why}
        </p>
      )}
    </li>
  );
}

export { LockKey };

// The evidence vault. Saved chats are encrypted with AES-GCM under a key derived from the
// child's PIN (PBKDF2, 310k rounds) and kept in IndexedDB on this device. The PIN is never
// stored; a small encrypted marker lets Ward check it. Each saved message also gets a SHA-256
// fingerprint, so a printed report can show the evidence wasn't edited after saving.

import type { Analysis, Chat } from "@ward/engine";
import { getState, updateProfile } from "./store.ts";

const DB = "ward-vault";
const STORE = "items";
const enc = new TextEncoder();
const dec = new TextDecoder();

export interface VaultItem {
  id: string;
  savedAt: number;
  title: string;
  self: string | null;
  chat: Chat;
  analysis: Analysis;
  /** sha256 of "sender|iso time|text" per message, in order. */
  fingerprints: string[];
  note?: string;
}

let key: CryptoKey | null = null;

const b64 = (b: ArrayBuffer | Uint8Array) => btoa(String.fromCharCode(...new Uint8Array(b instanceof Uint8Array ? b : new Uint8Array(b))));
const unb64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

async function derive(pin: string, salt: Uint8Array) {
  const base = await crypto.subtle.importKey("raw", enc.encode(pin), "PBKDF2", false, ["deriveKey"]);
  return crypto.subtle.deriveKey({ name: "PBKDF2", salt, iterations: 310_000, hash: "SHA-256" }, base, { name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
}

async function seal(k: CryptoKey, data: string) {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, k, enc.encode(data));
  return `${b64(iv)}.${b64(ct)}`;
}

async function open(k: CryptoKey, sealed: string) {
  const [iv, ct] = sealed.split(".");
  const pt = await crypto.subtle.decrypt({ name: "AES-GCM", iv: unb64(iv!) }, k, unb64(ct!));
  return dec.decode(pt);
}

export const hasPin = () => Boolean(getState().profile.vaultSalt);
export const isUnlocked = () => key !== null;
export const lock = () => {
  key = null;
};

export async function createPin(pin: string) {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  key = await derive(pin, salt);
  updateProfile({ vaultSalt: b64(salt), vaultCheck: await seal(key, "ward") });
}

export async function unlock(pin: string): Promise<boolean> {
  const { vaultSalt, vaultCheck } = getState().profile;
  if (!vaultSalt || !vaultCheck) return false;
  const k = await derive(pin, unb64(vaultSalt));
  try {
    if ((await open(k, vaultCheck)) !== "ward") return false;
    key = k;
    return true;
  } catch {
    return false;
  }
}

function db(): Promise<IDBDatabase> {
  return new Promise((res, rej) => {
    const r = indexedDB.open(DB, 1);
    r.onupgradeneeded = () => r.result.createObjectStore(STORE, { keyPath: "id" });
    r.onsuccess = () => res(r.result);
    r.onerror = () => rej(r.error);
  });
}

function tx<T>(mode: IDBTransactionMode, fn: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  return db().then(
    (d) =>
      new Promise<T>((res, rej) => {
        const req = fn(d.transaction(STORE, mode).objectStore(STORE));
        req.onsuccess = () => res(req.result);
        req.onerror = () => rej(req.error);
      }),
  );
}

async function sha256(s: string) {
  const h = await crypto.subtle.digest("SHA-256", enc.encode(s));
  return [...new Uint8Array(h)].map((x) => x.toString(16).padStart(2, "0")).join("");
}

export async function fingerprint(chat: Chat) {
  return Promise.all(chat.messages.map((m) => sha256(`${m.sender}|${m.at?.toISOString() ?? ""}|${m.text}`)));
}

/** Dates don't survive JSON; bring them back on the way out. */
function revive(item: VaultItem): VaultItem {
  const fix = (m: { at: string | Date | null }) => {
    m.at = m.at ? new Date(m.at) : null;
  };
  item.chat.messages.forEach(fix);
  item.chat.events.forEach(fix as never);
  item.analysis.findings.forEach((f) => fix(f.message));
  return item;
}

export async function save(item: Omit<VaultItem, "fingerprints" | "savedAt">) {
  if (!key) throw new Error("locked");
  const full: VaultItem = { ...item, savedAt: Date.now(), fingerprints: await fingerprint(item.chat) };
  const blob = await seal(key, JSON.stringify(full));
  await tx("readwrite", (s) => s.put({ id: item.id, blob }));
  updateProfile((p) => ({ checks: p.checks.map((c) => (c.id === item.id ? { ...c, saved: true } : c)) }));
}

export async function list(): Promise<VaultItem[]> {
  if (!key) throw new Error("locked");
  const rows = await tx<{ id: string; blob: string }[]>("readonly", (s) => s.getAll());
  const out: VaultItem[] = [];
  for (const r of rows) {
    try {
      out.push(revive(JSON.parse(await open(key, r.blob))));
    } catch {
      // A row from an older PIN: skip rather than fail the whole list.
    }
  }
  return out.sort((a, b) => b.savedAt - a.savedAt);
}

export async function remove(id: string) {
  await tx("readwrite", (s) => s.delete(id));
  updateProfile((p) => ({ checks: p.checks.map((c) => (c.id === id ? { ...c, saved: false } : c)) }));
}

/** Wipes the vault and the PIN. For "forgot my PIN" and "delete everything". */
export async function wipe() {
  key = null;
  await new Promise<void>((res) => {
    const r = indexedDB.deleteDatabase(DB);
    r.onsuccess = r.onerror = r.onblocked = () => res();
  });
  updateProfile((p) => ({ vaultSalt: null, vaultCheck: null, checks: p.checks.map((c) => ({ ...c, saved: false })) }));
}

import { useEffect, useRef, useState } from "react";
import { motion, useAnimationControls } from "motion/react";
import { Backspace } from "@phosphor-icons/react";

/** Four big digits and a keypad that works with touch and a keyboard alike. */
export function PinPad({ title, hint, onDone }: { title: string; hint?: string; onDone: (pin: string) => Promise<boolean | void> | boolean | void }) {
  const [pin, setPin] = useState("");
  const [busy, setBusy] = useState(false);
  const controls = useAnimationControls();
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => ref.current?.focus(), []);

  async function press(d: string) {
    if (busy) return;
    const next = (pin + d).slice(0, 4);
    setPin(next);
    if (next.length === 4) {
      setBusy(true);
      const ok = await onDone(next);
      setBusy(false);
      if (ok === false) {
        await controls.start({ x: [0, -10, 10, -6, 6, 0], transition: { duration: 0.35 } });
        setPin("");
      }
    }
  }

  return (
    <div
      ref={ref}
      tabIndex={-1}
      onKeyDown={(e) => {
        if (/^\d$/.test(e.key)) press(e.key);
        if (e.key === "Backspace") setPin((p) => p.slice(0, -1));
      }}
      className="mx-auto flex max-w-xs flex-col items-center outline-none"
    >
      <h2 className="text-center font-display text-2xl font-bold tracking-tight">{title}</h2>
      {hint && <p className="mt-2 text-center text-dim">{hint}</p>}
      <motion.div animate={controls} className="my-7 flex gap-4" aria-live="polite" aria-label={`${pin.length} of 4 digits entered`}>
        {[0, 1, 2, 3].map((i) => (
          <span key={i} className={`size-4 rounded-full transition-colors ${i < pin.length ? "bg-glow" : "bg-raised"}`} />
        ))}
      </motion.div>
      <div className="grid w-full grid-cols-3 gap-3">
        {["1", "2", "3", "4", "5", "6", "7", "8", "9", "", "0", "del"].map((k) =>
          k === "" ? (
            <span key="blank" />
          ) : (
            <button
              key={k}
              onClick={() => (k === "del" ? setPin((p) => p.slice(0, -1)) : press(k))}
              aria-label={k === "del" ? "Delete" : k}
              className="grid h-16 place-items-center rounded-btn bg-raised font-display text-2xl font-semibold active:scale-95"
            >
              {k === "del" ? <Backspace size={24} /> : k}
            </button>
          ),
        )}
      </div>
    </div>
  );
}

// "Save to vault" with the PIN steps inline: create one the first time, unlock after that.

import { useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { CheckCircle, LockKey, X } from "@phosphor-icons/react";
import { Button } from "./ui.tsx";
import { PinPad } from "./PinPad.tsx";
import { createPin, hasPin, isUnlocked, save, unlock } from "../lib/vault.ts";
import { useStore } from "../lib/store.ts";

export function SaveToVault({ id }: { id: string }) {
  const s = useStore((st) => st.sessions[id]);
  const saved = useStore((st) => st.profile.checks.find((c) => c.id === id)?.saved ?? false);
  const [step, setStep] = useState<null | "create" | "confirm" | "unlock">(null);
  const [first, setFirst] = useState("");

  async function doSave() {
    if (!s) return;
    await save({ id, title: s.title, self: s.self, chat: s.chat, analysis: s.analysis });
    setStep(null);
  }

  if (saved)
    return (
      <Button tone="quiet" disabled>
        <CheckCircle size={20} weight="fill" className="text-safe" /> Saved in vault
      </Button>
    );

  return (
    <>
      <Button
        tone="quiet"
        onClick={() => {
          if (!hasPin()) setStep("create");
          else if (!isUnlocked()) setStep("unlock");
          else void doSave();
        }}
      >
        <LockKey size={20} weight="bold" /> Save as evidence
      </Button>
      <AnimatePresence>
        {step && (
          <motion.div
            role="dialog"
            aria-modal
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-40 grid place-items-center bg-[color-mix(in_srgb,var(--bg),transparent_15%)] p-4 backdrop-blur-md"
          >
            <motion.div initial={{ y: 24 }} animate={{ y: 0 }} className="relative w-full max-w-sm rounded-card border border-line bg-surface p-6 pt-10">
              <button onClick={() => setStep(null)} className="absolute right-3 top-3 grid size-11 place-items-center rounded-full text-dim hover:bg-raised" aria-label="Close">
                <X size={20} weight="bold" />
              </button>
              {step === "create" && (
                <PinPad
                  title="Make a vault PIN"
                  hint="Four numbers only you know. Without it, nobody can open your evidence, not even me."
                  onDone={(p) => {
                    setFirst(p);
                    setStep("confirm");
                  }}
                />
              )}
              {step === "confirm" && (
                <PinPad
                  key="confirm"
                  title="Once more"
                  hint="Type the same PIN again."
                  onDone={async (p) => {
                    if (p !== first) {
                      setStep("create");
                      return false;
                    }
                    await createPin(p);
                    await doSave();
                  }}
                />
              )}
              {step === "unlock" && (
                <PinPad
                  title="Unlock your vault"
                  onDone={async (p) => {
                    if (!(await unlock(p))) return false;
                    await doSave();
                  }}
                />
              )}
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

// A message the child can send to a trusted adult, written from what Ward found. Gemma writes it
// in a child's voice when it's available; otherwise a plain template does the same job. The
// message never quotes the slurs: it says what kind of thing is happening, for how long.

import type { Analysis } from "@ward/engine";
import { getState } from "./store.ts";

const KIND_WORDS: Record<string, string> = {
  danger: "some messages threaten me",
  campaign: "the same person keeps going after me",
  pileon: "a group of people piled on me at once",
  ghosts: "new accounts were added just to send me mean messages",
  exclusion: "people are trying to keep me out",
  nightwatch: "a lot of it happens late at night",
  escalating: "it's getting worse",
};

export function templateDraft(a: Analysis, where: string, adult: string): string {
  const kinds = a.patterns.map((p) => KIND_WORDS[p.kind]).filter(Boolean);
  const days = new Set(a.findings.filter((f) => f.severity > 0 && f.message.at).map((f) => f.message.at!.toDateString())).size;
  const since = days > 1 ? ` It's been going on for ${days} days.` : "";
  return [
    `${adult ? `Hi ${adult}, c` : "C"}an we talk soon? Something is happening in ${where} and I need help.`,
    kinds.length ? `${kinds[0]![0]!.toUpperCase()}${kinds.slice(0, 3).join(", and ").slice(1)}.${since}` : `People are being mean to me there.${since}`,
    "I've saved the messages so I can show you. Please don't be angry, I just want it to stop.",
  ].join(" ");
}

export async function gemmaDraft(a: Analysis, where: string, adult: string, age: string): Promise<string | null> {
  const { ollamaUrl, model } = getState().profile;
  const facts = [
    ...a.patterns.map((p) => `- ${p.summary}`),
    `- ${a.findings.filter((f) => f.severity > 0).length} hurtful messages`,
  ].join("\n");
  try {
    const r = await fetch(`${ollamaUrl}/api/chat`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      signal: AbortSignal.timeout(45_000),
      body: JSON.stringify({
        model,
        stream: false,
        think: false,
        options: { temperature: 0.4 },
        messages: [
          {
            role: "user",
            content: `Write a short text message (3 or 4 sentences) from a child aged ${age === "8" ? "8 to 10" : age === "11" ? "11 to 13" : "14 to 17"} to ${adult || "a trusted adult"}, asking for help because they are being bullied in "${where}". Use simple, honest words a child that age would use. Do not quote any insults. Mention they saved the messages. Facts:\n${facts}\nReply with only the message.`,
          },
        ],
      }),
    });
    if (!r.ok) return null;
    const j = (await r.json()) as { message: { content: string } };
    return j.message.content.trim().replace(/^"|"$/g, "") || null;
  } catch {
    return null;
  }
}

// What to do now, in order: don't feed it, save it, shut the door, tell someone. Ward drafts the
// message to a trusted adult; the child copies or shares it themselves.

import { useEffect, useState } from "react";
import { ChatCircleDots, Copy, HandPalm, MoonStars, PaperPlaneTilt, ShieldCheck, Sparkle } from "@phosphor-icons/react";
import { Ghost } from "../components/Ghost.tsx";
import { HelpNow } from "../components/HelpNow.tsx";
import { SaveToVault } from "../components/SaveToVault.tsx";
import { BackBar, Button, Screen } from "../components/ui.tsx";
import { gemmaDraft, templateDraft } from "../lib/draft.ts";
import { updateProfile, useStore } from "../lib/store.ts";

const APPS = {
  WhatsApp: [
    "Open the chat and tap their name at the top.",
    "Scroll down and tap Report. WhatsApp gets the last few messages so they can see what happened. They aren't told it was you.",
    "Tap Block. For a group: tap the group name, then Exit group, or Report group.",
    "Mute a group at night: group name, then Notifications, then Mute.",
  ],
  Instagram: [
    "Press and hold a mean message or comment, then tap Report.",
    "On their profile, tap the three dots at the top right, then Block. Restrict is a quieter option: they won't know, and you won't see their comments.",
    "Reports are anonymous.",
  ],
  TikTok: [
    "Press and hold a mean comment, then tap Report.",
    "On their profile, tap the share arrow at the top right, then Report or Block.",
    "In Settings, Privacy, you can limit who comments on your videos.",
  ],
  Snapchat: [
    "Press and hold their name in your chats.",
    "Tap Manage Friendship, then Report or Block.",
    "Snaps can be screenshotted. Save evidence with screenshots of your own before you block.",
  ],
  Discord: [
    "Press and hold (or right-click) a message, then Report Message.",
    "Tap their name, then the three dots, then Block.",
    "Tell a server moderator too: they can remove people from the server.",
  ],
} as const;

export function Coach({ id }: { id: string }) {
  const s = useStore((st) => st.sessions[id]);
  const p = useStore((st) => st.profile);
  const [app, setApp] = useState<keyof typeof APPS>(s?.chat.source === "whatsapp" ? "WhatsApp" : "WhatsApp");
  const [adult, setAdult] = useState(p.trusted[0]?.name ?? "");
  const [draft, setDraft] = useState("");
  const [drafting, setDrafting] = useState(false);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (s) setDraft(templateDraft(s.analysis, s.title, adult));
    // Only on open; regenerating is a button so the child's edits aren't lost.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  if (!s) return <Screen><BackBar /></Screen>;
  const danger = s.analysis.level === "urgent";
  const imageRisk = s.analysis.findings.some((f) => f.severity >= 3 && (f.categories.includes("sexual") || f.categories.includes("exposure")));

  return (
    <Screen>
      <BackBar title="What to do" />
      <div className="flex items-center gap-4">
        <Ghost mood="calm" size={72} />
        <p className="text-lg leading-relaxed">One step at a time. You don't have to do all of this today.</p>
      </div>

      {danger && (
        <div className="mt-6">
          <HelpNow images={imageRisk} />
        </div>
      )}

      <ol className="mt-8 grid gap-8">
        <Step n={1} icon={HandPalm} title="Don't reply to them">
          Replying angry is what they're hoping for, and it can make it look like you started it. You don't owe them an answer.
          {imageRisk && <b className="mt-2 block text-alarm">If someone is asking for photos or money, stop replying and never pay. It won't stop if you do.</b>}
        </Step>

        <Step n={2} icon={ShieldCheck} title="Keep the evidence">
          Save it before you block anyone, so the proof doesn't disappear.
          <div className="mt-3">
            <SaveToVault id={id} />
          </div>
        </Step>

        <Step n={3} icon={ChatCircleDots} title="Block, report, mute">
          <div className="mt-3 flex flex-wrap gap-2" role="tablist" aria-label="Which app">
            {(Object.keys(APPS) as (keyof typeof APPS)[]).map((k) => (
              <button
                key={k}
                role="tab"
                aria-selected={app === k}
                onClick={() => setApp(k)}
                className={`min-h-10 rounded-full px-4 text-sm font-bold ${app === k ? "bg-glow text-glow-ink" : "bg-raised text-dim hover:text-ink"}`}
              >
                {k}
              </button>
            ))}
          </div>
          <ul className="mt-4 grid list-disc gap-2 pl-5 marker:text-glow">
            {APPS[app].map((line) => (
              <li key={line}>{line}</li>
            ))}
          </ul>
        </Step>

        {s.analysis.patterns.some((p) => p.kind === "nightwatch") && (
          <Step n={4} icon={MoonStars} title="Close the door at night">
            Mute the chat after 9pm and charge your phone outside your room. The messages will still be there in the morning, when you're stronger and adults are awake.
          </Step>
        )}

        <Step n={s.analysis.patterns.some((p) => p.kind === "nightwatch") ? 5 : 4} icon={PaperPlaneTilt} title="Tell someone you trust">
          A parent, aunt, older cousin, teacher or counsellor. I wrote a message you can send. Change anything you like.
          <label htmlFor="adult" className="mt-4 block text-sm font-bold text-dim">
            Who are you sending it to?
          </label>
          <input
            id="adult"
            value={adult}
            onChange={(e) => setAdult(e.target.value)}
            onBlur={() => adult.trim() && !p.trusted.some((t) => t.name === adult.trim()) && updateProfile({ trusted: [{ name: adult.trim(), how: "" }, ...p.trusted].slice(0, 4) })}
            placeholder="Ammi, Mr Khan, Aunt Sara"
            className="mt-1.5 w-full rounded-btn border border-line bg-surface px-4 py-3 text-ink placeholder:text-dim/70 focus:border-glow focus:outline-none"
          />
          <label htmlFor="draft" className="mt-4 block text-sm font-bold text-dim">
            Your message
          </label>
          <textarea
            id="draft"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            rows={5}
            className="mt-1.5 w-full resize-y rounded-card border border-line bg-surface p-4 leading-relaxed text-ink focus:border-glow focus:outline-none"
          />
          <div className="mt-3 flex flex-wrap gap-2">
            <Button
              onClick={async () => {
                if (navigator.share) {
                  try {
                    await navigator.share({ text: draft });
                    return;
                  } catch {
                    // cancelled, or not allowed here: fall back to copy
                  }
                }
                await navigator.clipboard.writeText(draft);
                setCopied(true);
                setTimeout(() => setCopied(false), 2000);
              }}
            >
              {typeof navigator.share === "function" ? <PaperPlaneTilt size={18} weight="bold" /> : <Copy size={18} weight="bold" />}
              {copied ? "Copied" : typeof navigator.share === "function" ? "Share" : "Copy"}
            </Button>
            <Button
              tone="quiet"
              disabled={drafting}
              onClick={async () => {
                setDrafting(true);
                const d = (await gemmaDraft(s.analysis, s.title, adult, p.age)) ?? templateDraft(s.analysis, s.title, adult);
                setDraft(d);
                setDrafting(false);
              }}
            >
              <Sparkle size={18} weight="bold" /> {drafting ? "Writing…" : "Write it another way"}
            </Button>
          </div>
          <p className="mt-2 text-sm text-dim">I never send it myself. You choose if and when.</p>
        </Step>
      </ol>

      {!danger && (
        <div className="mt-12">
          <HelpNow />
        </div>
      )}
    </Screen>
  );
}

function Step({ n, icon: I, title, children }: { n: number; icon: typeof HandPalm; title: string; children: React.ReactNode }) {
