  .filter((x) => x.lo > 1.6)
  .sort((a, b) => b.lo - a.lo);
console.log(rows.length, "train rows", nb, "abusive");
console.log(scored.slice(0, 120).map((x) => `${x.w}(${x.c}/${x.o})`).join(" "));
