if (existsSync(synth)) {
  sources["Synthetic chats (Gemma 4 on this machine)"] = readFileSync(synth, "utf8")
    .split("\n")
    .filter(Boolean)
    .map((l) => JSON.parse(l))
    .map((r) => ({ text: r.text, hurtful: r.hurtful, danger: r.danger, lang: r.lang, source: `synthetic:${r.kind}` }));
