39	async function seal(k: CryptoKey, data: string) {
40	  const iv = crypto.getRandomValues(new Uint8Array(12));
41	  const ct = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, k, enc.encode(data));
42	  return `${b64(iv)}.${b64(ct)}`;
43	}
44	
45	async function open(k: CryptoKey, sealed: string) {
46	  const [iv, ct] = sealed.split(".");
47	  const pt = await crypto.subtle.decrypt({ name: "AES-GCM", iv: unb64(iv!) }, k, unb64(ct!));
48	  return dec.decode(pt);
49	}
