76	function db(): Promise<IDBDatabase> {
77	  return new Promise((res, rej) => {
78	    const r = indexedDB.open(vaultDbName(), 1);
79	    r.onupgradeneeded = () => r.result.createObjectStore(STORE, { keyPath: "id" });
80	    r.onsuccess = () => res(r.result);
81	    r.onerror = () => rej(r.error);
82	  });
83	}
