85	function tx<T>(mode: IDBTransactionMode, fn: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> {
86	  return db().then(
87	    (d) =>
88	      new Promise<T>((res, rej) => {
89	        const req = fn(d.transaction(STORE, mode).objectStore(STORE));
90	        req.onsuccess = () => res(req.result);
91	        req.onerror = () => rej(req.error);
92	      }),
93	  );
94	}
