98	/** Dates don't survive JSON; bring them back on the way out. */
99	function revive(item: VaultItem): VaultItem {
100	  const fix = (m: { at: string | Date | null }) => {
101	    m.at = m.at ? new Date(m.at) : null;
102	  };
103	  item.chat.messages.forEach(fix);
104	  item.chat.events.forEach(fix as never);
105	  item.analysis.findings.forEach((f) => fix(f.message));
106	  return item;
107	}
