109	export async function save(item: Omit<VaultItem, "fingerprints" | "savedAt">) {
110	  if (!key) throw new Error("locked");
111	  const full: VaultItem = { ...item, savedAt: Date.now(), fingerprints: await fingerprint(item.chat) };
112	  const blob = await seal(key, JSON.stringify(full));
113	  await tx("readwrite", (s) => s.put({ id: item.id, blob }));
114	  updateProfile((p) => ({ checks: p.checks.map((c) => (c.id === item.id ? { ...c, saved: true } : c)) }));
115	}
