117	export async function list(): Promise<VaultItem[]> {
118	  if (!key) throw new Error("locked");
119	  const rows = await tx<{ id: string; blob: string }[]>("readonly", (s) => s.getAll());
120	  const out: VaultItem[] = [];
121	  for (const r of rows) {
122	    try {
123	      out.push(revive(JSON.parse(await open(key, r.blob))));
124	    } catch {
125	      // A row from an older PIN: skip rather than fail the whole list.
126	    }
127	  }
128	  return out.sort((a, b) => b.savedAt - a.savedAt);
129	}
