# The Ward report format (`ward.report/v1`)

When a child makes a report in Ward, they get two files:

- **A page** (`Ward report - <chat>.html`) for a person to read or print.
- **`ward-report.json`**, the same report as data, so a helpline or school system can import it
  and check it wasn't changed.

Both are made on the child's device. Ward never sends them; the child chooses who gets them.

This format is a draft. It was written without a helpline yet, and the first thing we want is a
helpline's caseworkers telling us what's missing or in the wrong order. See
[ROADMAP.md](ROADMAP.md).

## Why a format

Helplines spend intake time reconstructing what happened from screenshots: who, when, how often,
whether there's a threat, what the child wants. Pakistan's Digital Rights Foundation helpline
took 3,012 new complaints in 2025, with cases involving minors up 28%. A report that arrives
complete saves that time on every case.

## Fields

| Field | What it holds |
| --- | --- |
| `schema` | Always `"ward.report/v1"`. |
| `createdAt` | When the report was made (ISO 8601). |
| `recipient` | Who the child made it for: `helpline`, `school`, `police` or `adult`. |
| `reporter` | Only what the child chose to share: `firstName`, `ageBand` (`"8"` = 8 to 10, `"11"` = 11 to 13, `"14"` = 14 to 17), `city`, `country`. Empty fields are left out. |
| `safety.inDangerNow` | The child's own answer: `true`, `false`, or `null` if they skipped it. |
| `safety.level` | Ward's overall reading: `calm`, `watch`, `bullying`, `urgent`. |
| `safety.dangerous` | Any of `threat`, `selfharm`, `sexual`, `exposure` present in the messages. |
| `wants` | What the child wants to happen, e.g. `{ "id": "remove", "label": "Get something taken down" }`. |
| `conversation` | Title, platform, `source` (`whatsapp` export or `paste`), message and participant counts, first and last hurtful message, number of days. |
| `accounts` | Each account that sent hurtful messages, as named in the chat: count, worst severity, whether it was added to the group during the chat, whether it only ever attacked. |
| `patterns` | Ward's pattern findings (`campaign`, `pileon`, `ghosts`, `exclusion`, `danger`, `nightwatch`, `escalating`) with one neutral, third-person sentence each (`fact`). |
| `incidents` | Every hurtful message: time, sender, exact text, severity (1 unkind, 2 bullying, 3 dangerous), categories, Ward's short note, and its SHA-256 fingerprint. |
| `integrity` | `savedAt` (when the evidence went into the vault), `algorithm`, and `digest`: SHA-256 of `JSON.stringify({ conversation, incidents })`. |
| `tool` | Ward's version, the model(s) that read the chat, and the slang packs used. |

## Checking a report

Recompute the digest and compare. In JavaScript, with the same function Ward uses
(`verifyReport` in `packages/engine/src/report.ts`):

```js
const digest = sha256(JSON.stringify({ conversation: r.conversation, incidents: r.incidents }));
digest === r.integrity.digest; // false if any message, time or count was edited
```

Each message fingerprint is `sha256(sender + "|" + ISO time + "|" + text)` at the moment it was
saved. What the fingerprints prove: the messages weren't changed after the child saved them.
What they don't prove: that the chat export itself was genuine. For that, a caseworker can ask
the child to show the conversation in WhatsApp.

## What's deliberately not in it

- The full chat. Only the hurtful messages go in; the rest of the conversation stays private.
- Messages the child sent, and messages from people who weren't hurtful (including anyone who
  stood up for them).
- Any guess at who is behind an anonymous account.
// A report a helpline, school or police officer can act on without a back-and-forth: who, what,
// when, how bad, what the child wants, and proof the messages weren't edited after saving.
// The format is versioned (ward.report/v1) and documented in docs/REPORT.md so a helpline can
// import it, not just read it.

import type { Analysis, Category, Chat, PatternKind, Severity } from "./types.ts";

export const WANTS = {
  stop: "Make it stop",
  remove: "Get something taken down",
  talk: "Talk to someone about how I feel",
  school: "Tell my school",
  police: "Report it to the police",
} as const;

export type Want = keyof typeof WANTS;

export interface ReportInput {
  chat: Chat;
  analysis: Analysis;
  /** SHA-256 per message, in chat order, taken when the evidence was saved. */
  fingerprints: string[];
  savedAt: Date;
  title: string;
  platform: string;
  /** Everything about the child is optional; the child decides what to share. */
  reporter: { firstName?: string; ageBand?: string; city?: string; country?: string };
  inDangerNow: boolean | null;
  wants: Want[];
  /** Who the report is for, so the wording can fit (helpline, school, police, parent). */
  recipient: "helpline" | "school" | "police" | "adult";
  appVersion?: string;
}

export interface ReportIncident {
  at: string | null;
  from: string;
  text: string;
  severity: Severity;
  categories: Category[];
  why: string;
  sha256: string;
}

export interface WardReport {
  schema: "ward.report/v1";
  createdAt: string;
  recipient: ReportInput["recipient"];
  tool: { name: "Ward"; version: string; models: string[]; languages: string[] };
  reporter: ReportInput["reporter"];
  safety: { inDangerNow: boolean | null; level: Analysis["level"]; dangerous: Category[] };
  wants: { id: Want; label: string }[];
  conversation: {
    title: string;
    platform: string;
    source: Chat["source"];
    messages: number;
    participants: number;
    firstIncident: string | null;
    lastIncident: string | null;
    days: number;
  };
  accounts: { name: string; hurtfulMessages: number; worstSeverity: Severity; addedDuringChat: boolean; onlyAttacked: boolean }[];
  patterns: { kind: PatternKind; fact: string }[];
  incidents: ReportIncident[];
  integrity: { algorithm: "SHA-256"; savedAt: string; perMessage: true; digest: string };
}

async function sha256(s: string) {
  const h = await globalThis.crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(h)].map((x) => x.toString(16).padStart(2, "0")).join("");
}

const DANGER: Category[] = ["threat", "selfharm", "sexual", "exposure"];

export async function buildReport(input: ReportInput): Promise<WardReport> {
  const { chat, analysis: a, fingerprints } = input;
  const self = a.self;
  const hurtful = a.findings.filter((f) => f.severity > 0 && f.message.sender !== self);
  const fp = new Map(chat.messages.map((m, i) => [m.id, fingerprints[i] ?? ""]));
  const incidents: ReportIncident[] = hurtful.map((f) => ({
    at: f.message.at?.toISOString() ?? null,
    from: f.message.sender,
    text: f.message.text,
    severity: f.severity,
    categories: f.categories,
    why: f.why,
    sha256: fp.get(f.message.id) ?? "",
  }));
  const times = incidents.map((i) => i.at).filter((t): t is string => !!t).sort();
  const ghosts = new Set(a.patterns.find((p) => p.kind === "ghosts")?.senders ?? []);
  const added = new Set(chat.events.filter((e) => e.kind === "added" || e.kind === "joined").map((e) => e.who));
  const conversation = {
    title: input.title,
    platform: input.platform,
    source: chat.source,
    messages: chat.messages.length,
    participants: chat.participants.length,
    firstIncident: times[0] ?? null,
    lastIncident: times.at(-1) ?? null,
    days: new Set(times.map((t) => t.slice(0, 10))).size,
  };
  // The digest covers what a reader relies on: the conversation facts and every incident.
  const digest = await sha256(JSON.stringify({ conversation, incidents }));
  return {
    schema: "ward.report/v1",
    createdAt: new Date().toISOString(),
    recipient: input.recipient,
    tool: { name: "Ward", version: input.appVersion ?? "0.1.0", models: a.layers.models, languages: a.layers.packs },
    reporter: Object.fromEntries(Object.entries(input.reporter).filter(([, v]) => v && String(v).trim())) as ReportInput["reporter"],
    safety: {
      inDangerNow: input.inDangerNow,
      level: a.level,
      dangerous: [...new Set(hurtful.flatMap((f) => f.categories).filter((c) => DANGER.includes(c)))],
    },
    wants: input.wants.map((id) => ({ id, label: WANTS[id] })),
    conversation,
    accounts: a.senders
      .filter((s) => s.hostile > 0 && s.name !== self)
      .map((s) => ({ name: s.name, hurtfulMessages: s.hostile, worstSeverity: s.worst, addedDuringChat: added.has(s.name), onlyAttacked: ghosts.has(s.name) })),
    patterns: a.patterns.map((p) => ({ kind: p.kind, fact: p.fact ?? p.summary })),
    incidents,
    integrity: { algorithm: "SHA-256", savedAt: input.savedAt.toISOString(), perMessage: true, digest },
  };
}

/** Recompute the digest of a received report, so a helpline can check it wasn't altered. */
export async function verifyReport(r: WardReport): Promise<boolean> {
  return (await sha256(JSON.stringify({ conversation: r.conversation, incidents: r.incidents }))) === r.integrity.digest;
}

export async function fingerprintMessages(chat: Chat): Promise<string[]> {
  return Promise.all(chat.messages.map((m) => sha256(`${m.sender}|${m.at?.toISOString() ?? ""}|${m.text}`)));
}

