1	// A report a helpline, school or police officer can act on without a back-and-forth: who, what,
2	// when, how bad, what the child wants, and proof the messages weren't edited after saving.
3	// The format is versioned (ward.report/v1) and documented in docs/REPORT.md so a helpline can
4	// import it, not just read it.
5	
6	import type { Analysis, Category, Chat, PatternKind, Severity } from "./types.ts";
7	
8	export const WANTS = {
9	  stop: "Make it stop",
10	  remove: "Get something taken down",
11	  talk: "Talk to someone about how I feel",
12	  school: "Tell my school",
13	  police: "Report it to the police",
14	} as const;
15	
16	export type Want = keyof typeof WANTS;
17	
18	export interface ReportInput {
19	  chat: Chat;
20	  analysis: Analysis;
21	  /** SHA-256 per message, in chat order, taken when the evidence was saved. */
22	  fingerprints: string[];
23	  savedAt: Date;
24	  title: string;
25	  platform: string;
26	  /** Everything about the child is optional; the child decides what to share. */
27	  reporter: { firstName?: string; ageBand?: string; city?: string; country?: string };
28	  inDangerNow: boolean | null;
29	  wants: Want[];
30	  /** Who the report is for, so the wording can fit (helpline, school, police, parent). */
31	  recipient: "helpline" | "school" | "police" | "adult";
32	  appVersion?: string;
33	}
34	
35	export interface ReportIncident {
36	  at: string | null;
37	  from: string;
38	  text: string;
39	  severity: Severity;
40	  categories: Category[];
41	  why: string;
42	  sha256: string;
43	}
44	
45	export interface WardReport {
46	  schema: "ward.report/v1";
47	  createdAt: string;
48	  recipient: ReportInput["recipient"];
49	  tool: { name: "Ward"; version: string; models: string[]; languages: string[] };
50	  reporter: ReportInput["reporter"];
51	  safety: { inDangerNow: boolean | null; level: Analysis["level"]; dangerous: Category[] };
52	  wants: { id: Want; label: string }[];
53	  conversation: {
54	    title: string;
55	    platform: string;
56	    source: Chat["source"];
57	    messages: number;
58	    participants: number;
59	    firstIncident: string | null;
60	    lastIncident: string | null;
61	    days: number;
62	  };
63	  accounts: { name: string; hurtfulMessages: number; worstSeverity: Severity; addedDuringChat: boolean; onlyAttacked: boolean }[];
64	  patterns: { kind: PatternKind; fact: string }[];
65	  incidents: ReportIncident[];
66	  integrity: { algorithm: "SHA-256"; savedAt: string; perMessage: true; digest: string };
67	}
68	
69	async function sha256(s: string) {
70	  const h = await globalThis.crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
71	  return [...new Uint8Array(h)].map((x) => x.toString(16).padStart(2, "0")).join("");
72	}
73	
74	const DANGER: Category[] = ["threat", "selfharm", "sexual", "exposure"];
75	
76	export async function buildReport(input: ReportInput): Promise<WardReport> {
77	  const { chat, analysis: a, fingerprints } = input;
78	  const self = a.self;
79	  const hurtful = a.findings.filter((f) => f.severity > 0 && f.message.sender !== self);
80	  const fp = new Map(chat.messages.map((m, i) => [m.id, fingerprints[i] ?? ""]));
81	  const incidents: ReportIncident[] = hurtful.map((f) => ({
82	    at: f.message.at?.toISOString() ?? null,
83	    from: f.message.sender,
84	    text: f.message.text,
85	    severity: f.severity,
86	    categories: f.categories,
87	    why: f.why,
88	    sha256: fp.get(f.message.id) ?? "",
89	  }));
90	  const times = incidents.map((i) => i.at).filter((t): t is string => !!t).sort();
91	  const ghosts = new Set(a.patterns.find((p) => p.kind === "ghosts")?.senders ?? []);
92	  const added = new Set(chat.events.filter((e) => e.kind === "added" || e.kind === "joined").map((e) => e.who));
93	  const conversation = {
94	    title: input.title,
95	    platform: input.platform,
96	    source: chat.source,
97	    messages: chat.messages.length,
98	    participants: chat.participants.length,
99	    firstIncident: times[0] ?? null,
100	    lastIncident: times.at(-1) ?? null,
101	    days: new Set(times.map((t) => t.slice(0, 10))).size,
102	  };
103	  // The digest covers what a reader relies on: the conversation facts and every incident.
104	  const digest = await sha256(JSON.stringify({ conversation, incidents }));
105	  return {
106	    schema: "ward.report/v1",
107	    createdAt: new Date().toISOString(),
108	    recipient: input.recipient,
109	    tool: { name: "Ward", version: input.appVersion ?? "0.1.0", models: a.layers.models, languages: a.layers.packs },
110	    reporter: Object.fromEntries(Object.entries(input.reporter).filter(([, v]) => v && String(v).trim())) as ReportInput["reporter"],
111	    safety: {
112	      inDangerNow: input.inDangerNow,
113	      level: a.level,
114	      dangerous: [...new Set(hurtful.flatMap((f) => f.categories).filter((c) => DANGER.includes(c)))],
115	    },
116	    wants: input.wants.map((id) => ({ id, label: WANTS[id] })),
117	    conversation,
118	    accounts: a.senders
119	      .filter((s) => s.hostile > 0 && s.name !== self)
120	      .map((s) => ({ name: s.name, hurtfulMessages: s.hostile, worstSeverity: s.worst, addedDuringChat: added.has(s.name), onlyAttacked: ghosts.has(s.name) })),
121	    patterns: a.patterns.map((p) => ({ kind: p.kind, fact: p.fact ?? p.summary })),
122	    incidents,
123	    integrity: { algorithm: "SHA-256", savedAt: input.savedAt.toISOString(), perMessage: true, digest },
124	  };
125	}
126	
127	/** Recompute the digest of a received report, so a helpline can check it wasn't altered. */
128	export async function verifyReport(r: WardReport): Promise<boolean> {
129	  return (await sha256(JSON.stringify({ conversation: r.conversation, incidents: r.incidents }))) === r.integrity.digest;
130	}
131	
132	/**
133	 * The full check a caseworker or counsellor needs: the digest, plus each incident against the
134	 * fingerprint taken when the child saved it, so an edit can be pinned to the message it touched.
135	 * The case viewer (viewer/ward-viewer.html) carries the same check inline.
136	 */
137	export async function checkReport(r: WardReport): Promise<{ digestOk: boolean; perMessage: boolean[] }> {
138	  const digestOk = await verifyReport(r);
139	  const perMessage = await Promise.all(r.incidents.map(async (i) => (await sha256(`${i.from}|${i.at ?? ""}|${i.text}`)) === i.sha256));
140	  return { digestOk, perMessage };
141	}
142	
143	/** A reason the object isn't a report this version of Ward can read, or null. */
144	export function reportProblem(r: unknown): string | null {
145	  const o = r as Partial<WardReport> | null;
146	  if (!o || typeof o !== "object" || !("schema" in o)) return "not-report";
147	  if (o.schema !== "ward.report/v1") return "schema";
148	  if (!o.conversation || !o.integrity || !o.safety || !Array.isArray(o.incidents)) return "incomplete";
149	  return null;
150	}
151	
152	export async function fingerprintMessages(chat: Chat): Promise<string[]> {
153	  return Promise.all(chat.messages.map((m) => sha256(`${m.sender}|${m.at?.toISOString() ?? ""}|${m.text}`)));
154	}
