// Builds viewer/sample-report.json from the engine's Roman Urdu pile-on fixture, with the same
// buildReport the app uses, and embeds it in ward-viewer.html for "Try a sample report".
// Run: node --experimental-strip-types viewer/make-sample.ts

import { readFileSync, writeFileSync } from "node:fs";
import { analyze, buildReport, fingerprintMessages, parseChat } from "../packages/engine/src/index.ts";

const chat = parseChat(readFileSync(new URL("../packages/engine/fixtures/pileon-roman-urdu.txt", import.meta.url), "utf8"));
const analysis = await analyze(chat, { self: "Ayesha" });
const report = await buildReport({
  chat,
  analysis,
  fingerprints: await fingerprintMessages(chat),
  savedAt: new Date("2026-10-15T10:00:00Z"),
  title: "8B Science (sample)",
  platform: "WhatsApp",
  reporter: { firstName: "Ayesha", ageBand: "11", city: "Lahore", country: "Pakistan" },
  inDangerNow: false,
  wants: ["stop", "school"],
  recipient: "helpline",
});
const json = JSON.stringify(report, null, 2);
writeFileSync(new URL("./sample-report.json", import.meta.url), json + "\n");

const page = new URL("./ward-viewer.html", import.meta.url);
const html = readFileSync(page, "utf8").replace(
  /(<script type="application\/json" id="sample">)[\s\S]*?(<\/script>)/,
  (_, a, b) => `${a}${JSON.stringify(report).replace(/</g, "\\u003c")}${b}`,
);
writeFileSync(page, html);
console.log(`sample: ${report.incidents.length} incidents, level ${report.safety.level}`);
// The viewer's checks must agree with the engine's: run the <verify> block from
// ward-viewer.html against reports the engine builds, untouched and tampered.
// Run: node --test --experimental-strip-types viewer/viewer.test.ts

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { verifyReport, type WardReport } from "../packages/engine/src/index.ts";

const html = readFileSync(new URL("./ward-viewer.html", import.meta.url), "utf8");
const block = html.match(/\/\* <verify>[\s\S]*?\/\* <\/verify> \*\//)![0];
const { checkReport, problem } = new Function(`${block}; return { checkReport, problem };`)() as {
  checkReport: (r: WardReport) => Promise<{ digestOk: boolean; perMessage: boolean[] }>;
  problem: (r: unknown) => string | null;
};
const sample = (): WardReport => JSON.parse(readFileSync(new URL("./sample-report.json", import.meta.url), "utf8"));

test("an untouched report checks out, the same as the engine says", async () => {
  const r = sample();
  const c = await checkReport(r);
  assert.equal(c.digestOk, true);
  assert.ok(c.perMessage.length > 0 && c.perMessage.every(Boolean));
  assert.equal(await verifyReport(r), true);
});

test("an edited message fails both the digest and its own fingerprint", async () => {
  const r = sample();
  r.incidents[1]!.text = "hi";
  const c = await checkReport(r);
  assert.equal(c.digestOk, false);
  assert.deepEqual(c.perMessage.map((ok, i) => ok || i), c.perMessage.map((_, i) => (i === 1 ? 1 : true)));
  assert.equal(await verifyReport(r), false);
});

test("a changed count or a removed message fails the digest", async () => {
  const more = sample();
  more.conversation.days = 1;
  assert.equal((await checkReport(more)).digestOk, false);
  const fewer = sample();
  fewer.incidents.pop();
  assert.equal((await checkReport(fewer)).digestOk, false);
});

test("files that aren't Ward reports get a plain reason", () => {
  assert.match(problem(null)!, /isn't a Ward report/);
  assert.match(problem({ schema: "other/v9" })!, /schema: other\/v9/);
  assert.match(problem({ schema: "ward.report/v1", conversation: {}, incidents: [], safety: {} })!, /integrity/);
  assert.equal(problem(sample()), null);
});
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { analyze, buildReport, checkReport, fingerprintMessages, parseChat, reportProblem, verifyReport } from "./index.ts";

const chat = parseChat(readFileSync(new URL("../fixtures/pileon-roman-urdu.txt", import.meta.url), "utf8"));

async function report() {
  const analysis = await analyze(chat, { self: "Ayesha" });
  return buildReport({
    chat,
    analysis,
    fingerprints: await fingerprintMessages(chat),
    savedAt: new Date("2026-10-15T10:00:00Z"),
    title: "8B Science",
    platform: "WhatsApp",
    reporter: { firstName: "Ayesha", ageBand: "11", city: "  " },
    inDangerNow: false,
    wants: ["stop", "school"],
    recipient: "helpline",
  });
}

test("a report has what a helpline needs to act", async () => {
  const r = await report();
  assert.equal(r.schema, "ward.report/v1");
  assert.equal(r.safety.level, "urgent");
  assert.ok(r.safety.dangerous.includes("selfharm"));
  assert.deepEqual(r.wants.map((w) => w.id), ["stop", "school"]);
  assert.equal(r.conversation.days, 3);
  assert.ok(r.incidents.every((i) => /^[0-9a-f]{64}$/.test(i.sha256)));
  assert.ok(!r.incidents.some((i) => i.from === "Ayesha" || i.from === "Zara"), "the child and the upstander aren't incidents");
  const ghost = r.accounts.find((x) => x.name === "xx.ghost.xx")!;
  assert.ok(ghost.addedDuringChat && ghost.onlyAttacked);
  // Written for a caseworker, not to the child.
  for (const p of r.patterns) assert.doesNotMatch(p.fact, /\byou(r)?\b/i, p.fact);
});

test("blank details the child left empty are dropped", async () => {
  const r = await report();
  assert.deepEqual(r.reporter, { firstName: "Ayesha", ageBand: "11" });
});

test("the digest catches an edited message", async () => {
  const r = await report();
  assert.ok(await verifyReport(r));
  r.incidents[0]!.text = "something nicer";
  assert.ok(!(await verifyReport(r)));
