async function sha256(s) {
  const h = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(h)].map((x) => x.toString(16).padStart(2, "0")).join("");
}

function problem(r) {
  if (!r || typeof r !== "object") return "This file isn't a Ward report.";
  if (r.schema !== "ward.report/v1") return `This isn't a Ward report this viewer knows (schema: ${String(r.schema ?? "none")}).`;
  for (const k of ["conversation", "incidents", "integrity", "safety"]) if (!r[k]) return `The report is missing its "${k}" section.`;
  if (!Array.isArray(r.incidents)) return "The report's incidents aren't a list.";
  return null;
}

async function checkReport(r) {
  const digestOk = (await sha256(JSON.stringify({ conversation: r.conversation, incidents: r.incidents }))) === r.integrity.digest;
  const perMessage = await Promise.all(r.incidents.map(async (i) => (await sha256(`${i.from}|${i.at ?? ""}|${i.text}`)) === i.sha256));
  return { digestOk, perMessage };
}
