export function loadLite() {
  loaded ??= (async () => {
    const meta = await fetch(`${BASE}ward-lite/ward-lite.json`).then((r) => {
      if (!r.ok) throw new Error("Ward Lite isn't in this build");
      return r.json() as Promise<Meta>;
