      AutoTokenizer.from_pretrained("ward-lite"),
      AutoModelForSequenceClassification.from_pretrained("ward-lite", { dtype: "q8", device: "wasm" }),
    ]);
    return { tok, model, meta };
  })();
  loaded.catch(() => (loaded = null));
  return loaded;
}

