    return null;
  }
}

export async function downloadPhoneGemma(onProgress: (loaded: number, total: number) => void) {
  const h = await GemmaPhone.addListener("progress", (p) => onProgress(p.loaded, p.total));
  try {
    await GemmaPhone.download();
  } finally {
    await h.remove();
  }
}

export const cancelPhoneGemma = () => GemmaPhone.cancelDownload();
export const removePhoneGemma = () => GemmaPhone.remove();

/**
 * Gemma 4 E2B on the phone writes; it doesn't judge. On the scorecard it caught about a third of
 * abuse (eval/results/scorecard.md) where Ward Lite catches 83 to 85% in a 38 MB model, so Ward
 * Lite reads the chats and the phone's Gemma drafts the message to a trusted adult and gives
 * feedback on written lesson answers, which a classifier can't do.
 */
export async function phoneWrite(prompt: string): Promise<string | null> {
  const s = await phoneStatus();
  if (!s?.downloaded) return null;
  try {
    await GemmaPhone.load();
    const text = (await GemmaPhone.generate({ system: "", prompt })).text.trim();
    return text || null;
  } catch {
    return null;
  }
}
 * llama.cpp's grammar holds the reply to the schema. Left to itself Gemma closes the list at once
 * ("messages": []), so the grammar also asks for exactly one entry per JUDGE line, and the prompt
 * spells the shape out in words.
 */
export const desktopTransport: Transport = (system, user, schema) => {
  const judged = (user.match(/^JUDGE #/gm) ?? []).length;
  const s = structuredClone(schema) as { properties?: { messages?: { minItems?: number; maxItems?: number } } };
  if (judged && s.properties?.messages) Object.assign(s.properties.messages, { minItems: judged, maxItems: judged });
  return desktop()!.gemma.generate({ system, prompt: `${user}\n\n${JSON_INSTRUCTION}`, schema: s, temperature: 0 });
};

/** Writing (the message to a trusted adult, feedback on lesson answers), when Ollama isn't there. */
export async function desktopWrite(prompt: string, temperature = 0.3): Promise<string | null> {
  if (!(await desktopReady())) return null;
  try {
    const text = (await desktop()!.gemma.generate({ prompt, temperature, maxTokens: 400 })).trim();
    return text || null;
  } catch {
    return null;
  }
}

