  { key: 'docs-claims', prompt: 'LENS: accuracy of public claims and open-source readiness. Cross-check README.md, docs/*.md, apps/discord/README.md, the viewer text, and in-app copy (i18n) against the actual code and results files: numbers (scorecard, red-team, everyday, model size, timings), feature claims ("nothing leaves the device", "works offline", "never sends anything itself"), platform claims, and stale statements (e.g. after Ward Lite retrain, report v2, new features). Also check contributor readiness: CONTRIBUTING, issue/PR templates, CODE_OF_CONDUCT, SECURITY, how to add a language or a slang pack, good-first-issues. List every inaccurate or stale claim with the correct statement.' },
]

const IDEAS = {
  type: 'object',
  properties: {
    ideas: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          why: { type: 'string', description: 'the problem it solves and the evidence for it' },
          how: { type: 'string', description: 'concrete steps, building on what exists in the repo' },
          effort: { type: 'string', enum: ['S', 'M', 'L', 'XL'] },
          horizon: { type: 'string', enum: ['now', 'weeks', 'months'] },
          risks: { type: 'string' },
          needsUser: { type: 'string' },
        },
        required: ['title', 'why', 'how', 'effort', 'horizon', 'risks', 'needsUser'],
      },
    },
  },
  required: ['ideas'],
}

const STRATEGISTS = [
  { key: 'product-bets', prompt: 'ROLE: product strategist. Propose 6-10 big bets that would make Ward genuinely amazing for children and the adults around them — not polish, but things that change outcomes or reach. Ground each in what exists in the repo and in evidence about cyberbullying interventions (e.g. whole-school programmes, bystander/upstander training, helpline intake pain points, platform reporting gaps, low-resource regions). Consider: context-aware reading on every phone, more languages, iOS, WhatsApp/Instagram/TikTok/Discord coverage, a parent/teacher companion that is NOT spyware, helpline integrations, a privacy-preserving way to learn from corrections (federated or opt-in), community slang-pack curation, a pilot design with schools in Pakistan. Use web search for evidence where useful and cite URLs.' },
  { key: 'dissemination', prompt: `ROLE: awareness and dissemination strategist. The owner plans to use their own "reels factory" pipeline to make 9 to 12 short animated story videos (TikTok-style) to help kids understand Ward, plus other awareness work. Design: (1) the series — audience by platform and age (note TikTok's minimum age is 13 and under-13 rules; consider YouTube Shorts/YouTube Kids, Instagram Reels, WhatsApp status, school screenings), episode list (9-12) mapped to Ward's units (Spot it, Shut it down, Save it, Say it, Back them up, Lock it down, Bounce back) and features, a recurring cast (Ward the friendly ghost; the stories' characters in packages/lessons/src/stories.ts), hooks, one clear call to action per episode, languages (English, Urdu, Roman Urdu), safeguarding rules for depicting bullying, self-harm and sextortion to minors (no method, no glamorising, helpline cards, platform policies); (2) a launch and outreach plan: schools, NGOs and helplines in Pakistan/India/Bangladesh, DEV/GitHub/open-source communities, Hacktoberfest, Digital Public Goods; (3) how to measure reach and whether it drives safe use. Read the stories and lessons to reuse their content and cast. Use web search to confirm platform age and content rules, citing URLs.` },
]

const VERDICT = {
  type: 'object',
  properties: {
    verdict: { type: 'string', enum: ['confirmed', 'corrected', 'refuted'] },
    notes: { type: 'string', description: 'what you checked and found' },
    severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
    recommendation: { type: 'string', description: 'the recommendation, corrected if needed' },
  },
  required: ['verdict', 'notes', 'severity', 'recommendation'],
}

const verify = (f, lens) => agent(
  `${CONTEXT}\n\nYou are a sceptical reviewer. Another auditor (lens: ${lens}) reported this finding. Check it against the actual code and docs in ${REPO}. Default to "refuted" if the evidence doesn't hold up (wrong file/line, behaviour not as described, already handled elsewhere, or not actually a problem); use "corrected" if the core is real but details, severity or the fix are wrong; "confirmed" only if you verified it yourself. Recalibrate severity honestly (critical = real harm to a child or a real data leak; high = blocks safe real-world use or a clearly wrong public claim).\n\nFINDING:\n${JSON.stringify(f, null, 2)}`,
  { label: `verify:${lens}:${f.title.slice(0, 40)}`, phase: 'Verify', schema: VERDICT },
)

phase('Audit')
const audited = await pipeline(
  LENS_LIST(),
  (l) => agent(`${CONTEXT}\n\n${l.prompt}`, { label: `audit:${l.key}`, phase: 'Audit', schema: FINDINGS }),
  (res, l) => res ? parallel(res.findings.map((f) => () => verify(f, l.key).then((v) => ({ ...f, lens: l.key, verdict: v })))).then((fs) => ({ lens: l.key, strengths: res.strengths, findings: fs.filter(Boolean) })) : null,
)
function LENS_LIST() { return LENSES }

phase('Ideas')
const ideas = (await parallel(STRATEGISTS.map((s) => () =>
  agent(`${CONTEXT}\n\n${s.prompt}`, { label: `ideas:${s.key}`, phase: 'Ideas', schema: IDEAS }).then((r) => r && { key: s.key, ideas: r.ideas }),
))).filter(Boolean)

const kept = audited.filter(Boolean).flatMap((a) => a.findings.filter((f) => f.verdict && f.verdict.verdict !== 'refuted').map((f) => ({
  lens: f.lens, title: f.title, severity: f.verdict.severity, evidence: f.evidence, impact: f.impact,
  recommendation: f.verdict.recommendation, effort: f.effort, horizon: f.horizon, needsUser: f.needsUser, check: f.verdict.verdict + ': ' + f.verdict.notes,
})))
const refuted = audited.filter(Boolean).flatMap((a) => a.findings.filter((f) => f.verdict && f.verdict.verdict === 'refuted').map((f) => ({ lens: f.lens, title: f.title, why: f.verdict.notes })))
const strengths = audited.filter(Boolean).flatMap((a) => a.strengths.map((s) => `[${a.lens}] ${s}`))
log(`${kept.length} findings survived verification, ${refuted.length} refuted`)

phase('Synthesise')
const report = await agent(`${CONTEXT}\n\nYou are the lead auditor. Write the final audit as a Markdown document for the project owner (plain, warm, specific English; no em dashes; short paragraphs; tables where they help). Use ONLY the verified findings, strengths and strategist ideas below; don't invent new facts. Structure:
1. "Where Ward stands" — a candid one-page summary: what's genuinely strong, the 3 to 5 most important problems.
2. "Fix first" — critical/high findings as a table (finding, why it matters, the fix, effort), ordered by harm to children first.
3. "The plan" — three horizons: Now (the next ~16 hours, hackathon window, only small safe things), Next few weeks, Next few months. Each item: what, why, how, effort, and whether it needs the owner.
4. "Make it amazing" — the big bets (merge product ideas), each with how it builds on what exists.
5. "Spreading the word" — the animated story series (9 to 12 episodes: title, age/platform, the lesson, the hook, the call to action), safeguarding rules for the videos, launch and outreach, measurement.
6. "Questions for you" — every decision or context only the owner can provide, grouped and numbered, each with the recommended answer.
7. Appendix: all remaining medium/low findings as a compact table, and the refuted findings in one line each (so nothing is silently dropped).

VERIFIED FINDINGS (${kept.length}):\n${JSON.stringify(kept)}\n\nSTRENGTHS:\n${JSON.stringify(strengths)}\n\nSTRATEGIST IDEAS:\n${JSON.stringify(ideas)}\n\nREFUTED (for the appendix):\n${JSON.stringify(refuted)}`, { label: 'synthesise', phase: 'Synthesise' })

return { report, counts: { kept: kept.length, refuted: refuted.length, ideas: ideas.reduce((n, i) => n + i.ideas.length, 0) }, kept }

